function Southkorea () {
    tiles.setCurrentTilemap(tilemap`level4`)
    mySprite = sprites.create(assets.image`heroWalkFront0 l1`, SpriteKind.Player)
    mySprite.setPosition(60, 60)
    controller.moveSprite(mySprite)
    scene.cameraFollowSprite(mySprite)
    info.setScore(0)
    game.showLongText("Collect 3 lanterns and then Escape the Maze", DialogLayout.Bottom)
    koreaTrueFalse = false
    koreaLevel = true
    canShoot = true
}
