scene.onOverlapTile(SpriteKind.Player, assets.tile`myTile6`, function (sprite4, location4) {
    if (info.score() >= 5) {
        tiles.setTileAt(location4, assets.tile`transparency16`)
        game.showLongText("Yay! You have collected all the pieces of the billboard!", DialogLayout.Center)
        music.stopAllSounds()
        sprites.destroyAllSpritesOfKind(SpriteKind.Text)
        sprites.destroyAllSpritesOfKind(SpriteKind.Player)
        sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
        sprites.destroyAllSpritesOfKind(SpriteKind.Enemy)
        sprites.destroyAllSpritesOfKind(SpriteKind.Food)
        Malaysia_cutscene()
    } else {
        game.showLongText("You haven't collected all the pieces yet! Come back later!", DialogLayout.Center)
        USA_sprite.setPosition(97, 28)
    }
})
