function Malaysia () {
    Player_sprite = sprites.create(assets.image`myImage19`, SpriteKind.Player)
    tiles.setCurrentTilemap(tilemap`level7`)
    Player_sprite.ay = 500
    scene.cameraFollowSprite(Player_sprite)
    tiles.placeOnRandomTile(Player_sprite, assets.tile`landing stair`)
    controller.moveSprite(Player_sprite, 100, 0)
    game.showLongText("Welcome to Malaysia! Malaysia is a country full of diverse cultures, delicious food and stunning natural landscapes. ", DialogLayout.Full)
    game.showLongText("Your task is to climb Malaysia's most famous towers, the Petronas Twin Towers and obtain Malaysia's national flower, the hibiscus. The Twin Towers stand at a height of 452 meters and were announced the tallest buildings in the world from 1998-2004.", DialogLayout.Full)
    Malaysialvforboolean = true
}
