function quiz2 () {
    sprites.destroyAllSpritesOfKind(SpriteKind.Player)
    sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
    sprites.destroyAllSpritesOfKind(SpriteKind.Food)
    sprites.destroyAllSpritesOfKind(SpriteKind.Enemy)
    info.setLife(2)
    QUIZOVERORNOT = false
    game.showLongText("Q1. What is the famous street food we learnt about in Mexico?", DialogLayout.Bottom)
    story.showPlayerChoices("Burrito", "Pizza", "Sushi", "Taco")
    if (story.checkLastAnswer("Burrito")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("Pizza")) {
        info.changeLifeBy(-1)
        game.showLongText("Correct!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("Sushi")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("Taco")) {
        game.showLongText("Correct!", DialogLayout.Bottom)
    }
    game.showLongText("Q2. What is the maximum speed the Asian Hornet can fly up to?", DialogLayout.Bottom)
    story.showPlayerChoices("30km/h", "20km/h", "40km/h", "50km/h")
    if (story.checkLastAnswer("30km/h")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("20km/h")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("50km/h")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("40km/h")) {
        game.showLongText("Correct!", DialogLayout.Bottom)
    }
    game.showLongText("Q3. How many people can play ping pong?", DialogLayout.Bottom)
    story.showPlayerChoices("2 or 4", "1 or 3")
    if (story.checkLastAnswer("2 or 4")) {
        game.showLongText("Correct!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("1 or 3")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    game.showLongText("Where is Times Square located in?", DialogLayout.Bottom)
    story.showPlayerChoices("Queens", "Brooklyn", "Manhattan")
    if (story.checkLastAnswer("Manhattan")) {
        game.showLongText("Correct!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("Brooklyn")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("Queens")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    game.showLongText("How tall are the Petronas Towers", DialogLayout.Bottom)
    story.showPlayerChoices("200m", "452m", "601m")
    if (story.checkLastAnswer("452m")) {
        game.showLongText("Correct!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("200m")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    if (story.checkLastAnswer("601m")) {
        info.changeLifeBy(-1)
        game.showLongText("Incorrect!", DialogLayout.Bottom)
    }
    QUIZOVERORNOT = true
}
