forever(function () {
    if (QUIZOVERORNOT == true) {
        QUIZOVERORNOT = false
        End_chest_AUS()
    }
    if (QUIZOVERORNOT == false && info.life() == 0) {
        info.setLife(0.5)
        color.startFade(color.Black, color.originalPalette)
        game.showLongText("Try again!", DialogLayout.Bottom)
        quiz2()
    }
})
forever(function () {
    if (Malaysialvforboolean) {
        if (Player_sprite.tileKindAt(TileDirection.Center, assets.tile`basic ladder`)) {
            controller.moveSprite(Player_sprite, 100, 50)
        } else if (Player_sprite.tileKindAt(TileDirection.Bottom, assets.tile`basic ladder`)) {
            controller.moveSprite(Player_sprite, 100, 50)
        } else if (Player_sprite.tileKindAt(TileDirection.Bottom, assets.tile`basic ladder`)) {
            controller.moveSprite(Player_sprite, 100, 50)
        } else if (Player_sprite.tileKindAt(TileDirection.Center, assets.tile`basic ladder`)) {
            controller.moveSprite(Player_sprite, 100, 50)
        } else {
            controller.moveSprite(Player_sprite, 100, 0)
        }
    }
})
forever(function () {
    if (info.score() >= 10 && chinagame == true) {
        game.showLongText("You have completed China!", DialogLayout.Bottom)
        sprites.destroyAllSpritesOfKind(SpriteKind.Player)
        sprites.destroyAllSpritesOfKind(SpriteKind.Text)
        sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
        chinagame = false
        Transition_to_SK()
    }
})
forever(function () {
    if (chinagame == true) {
        while (mySprite2.x > 158) {
            info.changeLifeBy(-1)
            mySprite2.x = -159
        }
    }
    if (chinagame == true && info.life() == 0) {
        game.showLongText("Retry the quest!", DialogLayout.Center)
        sprites.destroyAllSpritesOfKind(SpriteKind.Player)
        sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
        sprites.destroyAllSpritesOfKind(SpriteKind.Player)
        China()
    }
})
forever(function () {
    if (callfinallevel) {
        game.showLongText("You have completed Malaysia's quest!", DialogLayout.Center)
        callfinallevel = false
        Transition_to_AUS()
    }
})
